fn tree_budget(t:&BTreeMap<String,Entry>)->Result<()> { if t.len()>N{return Err(e("materialization entry budget exceeded"))}let mut dirs=BTreeSet::new(); for p in t.keys(){if x(p){continue}util::rel(p)?;for(i,_)in p.match_indices('/'){dirs.insert(&p[..i]);if t.len().checked_add(dirs.len()).is_none_or(|n|n>N){return Err(e("materialization directory and leaf budget exceeded"))}}} Ok(()) }
