fn choose(m:&M,hard:bool,overlay:&str)->(String,String){let mut order=vec!["overlayfs","hardlink-ro","copy"];if let Some(w)=&m.want{order.retain(|s|*s!=w);order.insert(0,w)}let mut why=Vec::new();for k in order{match k{"overlayfs"=>why.push(format!("skipped overlayfs: {overlay}; no safe persistent namespace-overlay materializer is implemented")),"reflink"=>why.push("skipped reflink: not implemented by the native or upstream backend".into()),"hardlink-ro" if !hard=>why.push("skipped hardlink-ro: private same-filesystem hardlink probe refused".into()),"hardlink-ro" if m.ro.is_empty()=>why.push("skipped hardlink-ro: no read-only paths declared".into()),"hardlink-ro"=>{why.push("hardlink-ro: declared read-only paths linked only to this writer's immutable Git-object lower mirror; all other paths copied".into());return(k.into(),why.join("; "))},_=>{why.push("copy: immutable Git objects, no shared source inodes or host mounts".into());return("copy".into(),why.join("; "))}}}unreachable!()}
