#[test]fn native_reclaim_collector_rejects_whole_undeclared_set(){let d=r();let v=View::load(d.path(),"agent/test",None).unwrap();let g=Git::open(d.path()).unwrap();let a=BTreeMap::from([("out/good".into(),f(b"good")),("rogue".into(),f(b"bad"))]);let (changes,undeclared,claimed)=collect(&v,&a,&b(),None,&g).unwrap();assert_eq!(undeclared,["rogue"]);assert!(changes.is_empty());assert!(claimed.is_empty());assert_eq!(View::load(d.path(),"agent/test",None).unwrap().rev,0);}
#[test]fn native_reclaim_pins_valid_files_and_reports_deletions(){let d=r();let mut v=View::load(d.path(),"agent/test",None).unwrap();v.write("out/old",b"before",None).unwrap();let g=Git::open(d.path()).unwrap();let a=BTreeMap::from([("out/new".into(),f(b"after"))]);let (changes,undeclared,claimed)=collect(&v,&a,&b(),Some(&["out".into()]),&g).unwrap();assert!(undeclared.is_empty());assert_eq!(claimed,["out/new","out/old"]);assert_eq!(changes["out/old"],None);v.apply_batch(&changes).unwrap();assert_eq!(v.read("out/new").unwrap().unwrap(),b"after");assert_eq!(v.read("out/old").unwrap(),None);}
