#[test]fn bounded_hostile_output_is_killed_and_capped(){let mut q=Command::new("/usr/bin/printf");q.arg("%01048577d").arg("0");let r=bounded(q,1000).unwrap();assert!(r.limit);assert!(r.out.len()<=O);let mut q=Command::new("/usr/bin/sleep");q.arg("2");let r=bounded(q,20).unwrap();assert!(r.timeout);assert_ne!(r.exit,0);}
