#[test]fn writable_new_leaf_declarations_prepare_parents_without_creating_leaf_directories(){let d=r();let v=View::load(d.path(),"agent/test",None).unwrap();let stage=D::open(d.path()).unwrap().child("stage",true).unwrap();let mut b=b();b.outputs=vec!["answer.txt".into(),"nested/answer.txt".into()];let declared=prepare(&stage,&v,&b,true).unwrap();assert_eq!(declared,b.outputs);assert!(stage.meta("answer.txt").unwrap().is_none());assert!(stage.child("nested",false).unwrap().meta("answer.txt").unwrap().is_none());b.cache=vec!["cache-dir".into()];prepare(&stage,&v,&b,true).unwrap();assert!(stage.child("cache-dir",false).is_ok());}

